// sync_fifo_driver.sv
class sync_fifo_driver extends uvm_driver #(sync_fifo_seq_item);
  `uvm_component_utils(sync_fifo_driver)

  virtual sync_fifo_if vif;

  function new(string name = "sync_fifo_driver", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db #(virtual sync_fifo_if)::get(this, "", "vif", vif))
      `uvm_fatal("NOVIF", "Virtual interface not found in config_db")
  endfunction

  task run_phase(uvm_phase phase);
    sync_fifo_seq_item item;

    // Initialize signals before reset completes
    @(posedge vif.clk);
    wait(vif.rst_n === 1'b1); // Wait for reset deassertion
    @(posedge vif.clk);       // Synchronize to clock after reset

    forever begin
      seq_item_port.get_next_item(item);
      drive_item(item);
      seq_item_port.item_done();
    end
  endtask

  // Drive a single transaction using the clocking block
  task drive_item(sync_fifo_seq_item item);
    @(vif.cb);
    vif.cb.w_en    <= item.w_en;
    vif.cb.r_en    <= item.r_en;
    vif.cb.wr_data <= item.wr_data;
  endtask
endclass

