// sync_fifo_scoreboard.sv
class sync_fifo_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(sync_fifo_scoreboard)

  uvm_analysis_imp #(sync_fifo_seq_item, sync_fifo_scoreboard) analysis_export;

  // Reference model: internal FIFO queue
  logic [7:0] ref_fifo [$];
  int         ref_count;
  bit         ref_full;
  bit         ref_empty;

  // One-cycle pipeline: expected rd_data is registered in the DUT,
  // so it appears on the bus the cycle AFTER r_en is asserted.
  bit         pending_read;
  logic [7:0] pending_expected_data;

  // One-cycle pipeline for flags: ref_full/ref_empty are computed
  // combinationally from the new ref_count, but DUT full/empty are
  // registered and reflect the PREVIOUS cycle's count.
  bit         prev_ref_full;
  bit         prev_ref_empty;

  // Statistics
  int write_count;
  int read_count;
  int match_count;
  int mismatch_count;

  function new(string name = "sync_fifo_scoreboard", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    analysis_export = new("analysis_export", this);
    ref_fifo.delete();
    ref_count       = 0;
    ref_full        = 0;
    ref_empty       = 1;
    prev_ref_full   = 0;
    prev_ref_empty  = 1;
    pending_read    = 0;
    pending_expected_data = 0;
    write_count     = 0;
    read_count      = 0;
    match_count     = 0;
    mismatch_count  = 0;
  endfunction

function void write(sync_fifo_seq_item txn);
  bit effective_write;
  bit effective_read;

  // ──────────────────────────────────────────────────────────
  // 1) Check rd_data against the expectation queued the previous
  //    cycle (DUT rd_data is registered).
  // ──────────────────────────────────────────────────────────
  if (pending_read) begin
    if (txn.rd_data === pending_expected_data) begin
      match_count++;
      `uvm_info("SB", $sformatf("MATCH: rd_data=0x%02h expected=0x%02h",
                                 txn.rd_data, pending_expected_data), UVM_HIGH)
    end else begin
      mismatch_count++;
      `uvm_error("SB", $sformatf("MISMATCH: rd_data=0x%02h expected=0x%02h",
                                  txn.rd_data, pending_expected_data))
    end
    pending_read = 0;
  end

  // ──────────────────────────────────────────────────────────
  // 2) Check DUT flags FIRST, against the CURRENT ref state.
  //    The DUT flags reflect the registered `count` from before
  //    this clock edge, which equals the ref state from before
  //    we apply this transaction.
  // ──────────────────────────────────────────────────────────
  if (txn.full !== ref_full) begin
    `uvm_warning("SB", $sformatf("Full flag mismatch: DUT=%0b REF=%0b (count=%0d)",
                                  txn.full, ref_full, ref_count))
  end
  if (txn.empty !== ref_empty) begin
    `uvm_warning("SB", $sformatf("Empty flag mismatch: DUT=%0b REF=%0b (count=%0d)",
                                  txn.empty, ref_empty, ref_count))
  end

  // ──────────────────────────────────────────────────────────
  // 3) NOW compute effective enables and update ref model
  //    (this transaction's effects take place on this edge,
  //    visible to DUT flags on the NEXT cycle's sample).
  // ──────────────────────────────────────────────────────────
  effective_read  = txn.r_en && !ref_empty;
  effective_write = txn.w_en && (!ref_full || effective_read);

  if (effective_write) begin
    ref_fifo.push_back(txn.wr_data);
    ref_count++;
    write_count++;
  end

  if (effective_read) begin
    pending_expected_data = ref_fifo.pop_front();
    pending_read = 1;
    ref_count--;
    read_count++;
  end

  // 4) Update ref flags from new count for next cycle's check.
  ref_empty = (ref_count == 0);
  ref_full  = (ref_count == 8);
endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("SB", $sformatf("===== Scoreboard Report ====="), UVM_NONE)
    `uvm_info("SB", $sformatf("  Total writes:    %0d", write_count), UVM_NONE)
    `uvm_info("SB", $sformatf("  Total reads:     %0d", read_count), UVM_NONE)
    `uvm_info("SB", $sformatf("  Data matches:    %0d", match_count), UVM_NONE)
    `uvm_info("SB", $sformatf("  Data mismatches: %0d", mismatch_count), UVM_NONE)
    `uvm_info("SB", $sformatf("  Remaining items: %0d", ref_fifo.size()), UVM_NONE)
    if (mismatch_count > 0)
      `uvm_error("SB", $sformatf("TEST FAILED: %0d mismatches found", mismatch_count))
    else
      `uvm_info("SB", "TEST PASSED: All data matches", UVM_NONE)
  endfunction
endclass

