// sync_fifo_coverage.sv
class sync_fifo_coverage extends uvm_subscriber #(sync_fifo_seq_item);
  `uvm_component_utils(sync_fifo_coverage)

  sync_fifo_seq_item txn;

  // Track FIFO occupancy for coverage
  int fifo_count;
  bit fifo_full;
  bit fifo_empty;

  covergroup cg_fifo_ops;
    option.per_instance = 1;

    // Write enable coverpoint
    cp_w_en: coverpoint txn.w_en {
      bins write_active = {1};
      bins write_inactive = {0};
    }

    // Read enable coverpoint
    cp_r_en: coverpoint txn.r_en {
      bins read_active = {1};
      bins read_inactive = {0};
    }

    // Operation type cross coverage
    cp_operation: cross cp_w_en, cp_r_en {
      bins idle       = binsof(cp_w_en.write_inactive) && binsof(cp_r_en.read_inactive);
      bins write_only = binsof(cp_w_en.write_active)   && binsof(cp_r_en.read_inactive);
      bins read_only  = binsof(cp_w_en.write_inactive) && binsof(cp_r_en.read_active);
      bins both       = binsof(cp_w_en.write_active)   && binsof(cp_r_en.read_active);
    }

    // Full flag
    cp_full: coverpoint txn.full {
      bins not_full = {0};
      bins is_full  = {1};
    }

    // Empty flag
    cp_empty: coverpoint txn.empty {
      bins not_empty = {0};
      bins is_empty  = {1};
    }

    // Write data corner values
    cp_wr_data: coverpoint txn.wr_data {
      bins zero     = {8'h00};
      bins max      = {8'hFF};
      bins low      = {[8'h01:8'h3F]};
      bins mid      = {[8'h40:8'hBF]};
      bins high     = {[8'hC0:8'hFE]};
    }

    // Read data corner values
    cp_rd_data: coverpoint txn.rd_data {
      bins zero     = {8'h00};
      bins max      = {8'hFF};
      bins low      = {[8'h01:8'h3F]};
      bins mid      = {[8'h40:8'hBF]};
      bins high     = {[8'hC0:8'hFE]};
    }

    // FIFO occupancy level
    cp_count: coverpoint fifo_count {
      bins empty   = {0};
      bins low     = {[1:2]};
      bins mid     = {[3:5]};
      bins high    = {[6:7]};
      bins full    = {8};
    }

    // Cross: operation vs FIFO state
    cp_write_when_full: cross cp_w_en, cp_full {
      bins write_at_full = binsof(cp_w_en.write_active) && binsof(cp_full.is_full);
    }

    cp_read_when_empty: cross cp_r_en, cp_empty {
      bins read_at_empty = binsof(cp_r_en.read_active) && binsof(cp_empty.is_empty);
    }

    // Cross: operation vs occupancy
    cp_ops_vs_count: cross cp_w_en, cp_r_en, cp_count;

    // Full-empty mutex (should never see both)
    cp_full_empty_mutex: cross cp_full, cp_empty {
      bins valid_states = !binsof(cp_full.is_full) || !binsof(cp_empty.is_empty);
      illegal_bins mutex_violation = binsof(cp_full.is_full) && binsof(cp_empty.is_empty);
    }
  endgroup

  function new(string name = "sync_fifo_coverage", uvm_component parent = null);
    super.new(name, parent);
    cg_fifo_ops = new();
    fifo_count = 0;
    fifo_full  = 0;
    fifo_empty = 1;
  endfunction

  function void write(sync_fifo_seq_item t);
    bit eff_wr, eff_rd;

    txn = t;

    eff_wr = t.w_en && !fifo_full;
    eff_rd = t.r_en && !fifo_empty;

    // Update reference count for occupancy coverage
    if (eff_wr && !eff_rd) fifo_count++;
    else if (!eff_wr && eff_rd) fifo_count--;
    // simultaneous or idle: no change

    fifo_full  = (fifo_count == 8);
    fifo_empty = (fifo_count == 0);

    cg_fifo_ops.sample();
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("COV", $sformatf("Functional Coverage: %.2f%%", cg_fifo_ops.get_inst_coverage()), UVM_NONE)
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// Agent (uvm_agent)
// ════════════════════════════════════════════════════════════

// sync_fifo_agent.sv
class sync_fifo_agent extends uvm_agent;
  `uvm_component_utils(sync_fifo_agent)

  sync_fifo_sequencer sqr;
  sync_fifo_driver    drv;
  sync_fifo_monitor   mon;

  uvm_analysis_port #(sync_fifo_seq_item) ap;

  function new(string name = "sync_fifo_agent", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    
    // Always create monitor
    mon = sync_fifo_monitor::type_id::create("mon", this);
    ap  = new("ap", this);

    // Create driver and sequencer only in ACTIVE mode
    if (get_is_active() == UVM_ACTIVE) begin
      drv = sync_fifo_driver::type_id::create("drv", this);
      sqr = sync_fifo_sequencer::type_id::create("sqr", this);
    end
  endfunction

  function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);
    
    // Connect monitor analysis port to agent analysis port
    mon.ap.connect(ap);

    // Connect driver to sequencer in ACTIVE mode
    if (get_is_active() == UVM_ACTIVE) begin
      drv.seq_item_port.connect(sqr.seq_item_export);
    end
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// Environment (uvm_env)
// ════════════════════════════════════════════════════════════

// sync_fifo_env.sv
class sync_fifo_env extends uvm_env;
  `uvm_component_utils(sync_fifo_env)

  sync_fifo_agent      agent;
  sync_fifo_scoreboard scoreboard;
  sync_fifo_coverage   coverage;

  function new(string name = "sync_fifo_env", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);

    agent      = sync_fifo_agent::type_id::create("agent", this);
    scoreboard = sync_fifo_scoreboard::type_id::create("scoreboard", this);
    coverage   = sync_fifo_coverage::type_id::create("coverage", this);
  endfunction

  function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);

    // Connect agent's analysis port to scoreboard and coverage
    agent.ap.connect(scoreboard.analysis_export);
    agent.ap.connect(coverage.analysis_export);
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// Test (uvm_test)
// ════════════════════════════════════════════════════════════

// sync_fifo_test.sv
class sync_fifo_base_test extends uvm_test;
  `uvm_component_utils(sync_fifo_base_test)

  sync_fifo_env env;

  function new(string name = "sync_fifo_base_test", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    env = sync_fifo_env::type_id::create("env", this);
  endfunction

  function void end_of_elaboration_phase(uvm_phase phase);
    super.end_of_elaboration_phase(phase);
    uvm_top.print_topology();
  endfunction

  task run_phase(uvm_phase phase);
    sync_fifo_master_seq master_seq;

    phase.raise_objection(this, "Starting sync_fifo_base_test");

    master_seq = sync_fifo_master_seq::type_id::create("master_seq");
    master_seq.start(env.agent.sqr);

    // Allow time for final transactions to propagate
    #100;
    
    phase.drop_objection(this, "Finished sync_fifo_base_test");
  endtask

  function void report_phase(uvm_phase phase);
    uvm_report_server svr;
    super.report_phase(phase);
    svr = uvm_report_server::get_server();
    if (svr.get_severity_count(UVM_ERROR) == 0 &&
        svr.get_severity_count(UVM_FATAL) == 0) begin
      `uvm_info("TEST", "========== TEST PASSED ==========", UVM_NONE)
    end else begin
      `uvm_info("TEST", "========== TEST FAILED ==========", UVM_NONE)
    end
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// UVM Top (tb_top)
// ════════════════════════════════════════════════════════════

// tb_top.sv


module tb_top;


  // Clock generation: 10ns period (100 MHz)
  logic clk;
  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  // Instantiate the interface
  sync_fifo_if fifo_if(.clk(clk));

  // Reset generation
  initial begin
    fifo_if.rst_n = 1'b0;   // Assert reset
    fifo_if.w_en  = 1'b0;
    fifo_if.r_en  = 1'b0;
    fifo_if.wr_data = 8'h00;
    repeat (5) @(posedge clk);
    fifo_if.rst_n = 1'b1;   // Deassert reset
    `uvm_info("TB_TOP", "Reset deasserted", UVM_MEDIUM)
  end

  // Instantiate the DUT and connect via interface
  sync_fifo dut (
    .clk     (clk),
    .rst_n   (fifo_if.rst_n),
    .w_en    (fifo_if.w_en),
    .r_en    (fifo_if.r_en),
    .wr_data (fifo_if.wr_data),
    .rd_data (fifo_if.rd_data),
    .full    (fifo_if.full),
    .empty   (fifo_if.empty)
  );

  // Store virtual interface in config_db for UVM components
  initial begin
    uvm_config_db #(virtual sync_fifo_if)::set(null, "*", "vif", fifo_if);
  end

  // Start UVM test
  initial begin
    run_test("sync_fifo_base_test");
  end

  // Simulation timeout safeguard
  initial begin
    #100_000;
    `uvm_fatal("TB_TOP", "Simulation timeout!")
  end

  // Optional: dump waveforms
  initial begin
    $dumpfile("sync_fifo.vcd");
    $dumpvars(0, tb_top);
  end
endmodule

